; Losing a fall, switching players and the game over screen
; $1818-$19b7

; Bruce has lost a fall. Silences the sound. In the demo: back to the title (title music next time).
; Else decrements falls_left; negative goes to game_over. Else (next_turn): actor_energy of all three actors
; = $24, enemy_follow_x cleared, fireball sprite rows cleared. In a two-player game where the other player
; still has falls (falls_left in inactive_player_state not negative) it switches current_player. Shows the
; PLAYER n screen; on a switch it also exchanges the player block $28-$43 (falls_left ... score) with
; inactive_player_state, the lantern states (swap_player_lanterns) and bonus_fall_next_score of the two
; players. Then resets the game screen (reset_play_state, spawns Bruce) and enters the room again
; (place_bruce_at_room_start). Called by actor_continue_action (end of a death) and check_actor_knockouts
; (Bruce knocked out).
lose_fall
        jsr stop_all_sounds             ; silence all sound
        lda game_mode
        bne lose_fall_count
        sta title_music_skip_count      ; title music on the next title screen
        jmp show_title_screen
lose_fall_count
        dec falls_left
        bmi game_over
next_turn
        lda #$24                        ; full energy for all three actors
        sta actor_energy
        sta actor_energy+1
        sta actor_energy+2
        lda #$00
        sta enemy_follow_x
        sta enemy_follow_x+1
        jsr clear_fireball_sprites      ; clear the fireball sprite rows
        lda option_two_players
        beq next_turn_player_screen
        lda inactive_player_state       ; falls_left of the other player: negative = that player is out
        bmi next_turn_player_screen
        lda current_player              ; switch to the other player
        eor #$01
        sta current_player
next_turn_player_screen
        jsr show_player_screen
        lda SCROLY
        and #$ef                        ; blank the display
        sta SCROLY
        lda option_two_players
        beq next_turn_enter_room
        lda inactive_player_state
        bmi next_turn_enter_room
; Exchange the player block $28-$43 (falls_left ... score) with inactive_player_state.
        ldx #$1b
next_turn_swap_block_loop
        lda falls_left,x
        ldy inactive_player_state,x
        sta inactive_player_state,x
        tya
        sta falls_left,x
        dex
        bpl next_turn_swap_block_loop
        jsr swap_player_lanterns        ; exchange the lantern flags
; Exchange bonus_fall_next_score with the other player's copy.
        ldx #$02
next_turn_swap_score_loop
        lda bonus_fall_next_score,x
        pha
        lda bonus_fall_next_score_other,x
        sta bonus_fall_next_score,x
        pla
        sta bonus_fall_next_score_other,x
        dex
        bpl next_turn_swap_score_loop
next_turn_enter_room
        jsr reset_play_state            ; reset the game screen and spawn Bruce
        ldx room
        jmp place_bruce_at_room_start   ; enter room X
; Game over screen of the current player. Clears the fireball sprite rows and the text screen, installs
; irq_title_frame at raster line $FB with a blue screen, fills screen rows 0-9 with the blank logo character,
; draws the big GAME OVER text (game_over_letters_top/bottom) on rows 1-2, PLAYER n on rows 5-6 and the
; 6-digit score in big digits on rows 8-9, then waits 254 frames. In a two-player game where the other
; player still has falls it continues with next_turn; else it waits 64 more frames and goes to
; show_title_screen.
game_over
        jsr clear_fireball_sprites
        jsr clear_text_screen           ; clear the text screen
        sei
        lda SCROLY                      ; blank the display
        and #$ef
        sta SCROLY
        lda #$00
        sta SPENA                       ; $d015: sprites 
; Next IRQ: irq_title_frame at raster line $FB.
        lda #<irq_title_frame
        sta irq_vector
        lda #>irq_title_frame
        sta irq_vector_hi
        lda #$01
        sta IRQMSK                      ; $d01a: sources raster
        sta VICIRQ
        lda SCROLY
        and #$7f
        sta SCROLY
        lda #$fb
        sta RASTER
        lda #$06                        ; blue border and background
        sta EXTCOL
        sta BGCOL0
        lda #$0f                        ; light grey multicolours
        sta BGCOL1
        sta BGCOL2
        ldx #$08
        stx SCROLX                      ; hires, 40 columns
        jsr fill_colour_ram             ; colour RAM = $0F
; Colour RAM rows 12-24 white; screen rows 0-9 blank logo characters.
        ldx #$00
game_over_clear_loop
        lda #$f1                        ; white for rows 12-24
        sta $d800+12*40,x
        sta $d800+12*40+256,x
        lda #$dc                        ; blank logo character on rows 0-9
        sta game_screen,x
        sta game_screen+10*40-256,x
        inx
        bne game_over_clear_loop
; GAME OVER in big letters on rows 1-2, column 11.
        ldx #$11
game_over_text_loop
        lda game_over_letters_top,x
        ora #$80                        ; bit 7: characters 128-255 of the logo charset
        sta game_screen+1*40+11,x
        lda game_over_letters_bottom,x
        ora #$80
        sta game_screen+2*40+11,x
        dex
        bpl game_over_text_loop
; Big digit of the player into the PLAYER banner. The loop runs once (DEY/BPL from 0), so only the first
; character of each half is copied; the second keeps the value of the last PLAYER n screen.
        lda current_player
        asl
        tax
        ldy #$00
; Bug: the loop runs once (DEY/BPL from Y = 0), so only the left half of the player digit is copied. No visible
; effect: lose_fall shows the PLAYER n screen of the current player at the start of each fall, so the right half
; is already the digit of the same player.
game_over_digit_loop
        lda player_banner_digit_top,x
        sta player_banner_top+$e,y
        lda player_banner_digit_bottom,x
        sta player_banner_bottom+$e,y
        dey
        bpl game_over_digit_loop
; PLAYER n banner on rows 5-6, column 12.
        ldx #$0f
game_over_player_loop
        lda player_banner_top,x
        ora #$80
        sta game_screen+5*40+12,x
        lda player_banner_bottom,x
        ora #$80
        sta game_screen+6*40+12,x
        dex
        bpl game_over_player_loop
        jsr score_to_bcd                ; score to BCD digits in bcd_conv_digits
; Score digits: upper row at screen row 8, lower row at row 9, column 14 (row_ptr_top, data_ptr).
        lda #<(game_screen+8*40+14)
        sta row_ptr_top
        lda #<(game_screen+9*40+14)
        sta data_ptr
        lda #>(game_screen+8*40+14)
        sta row_ptr_top+1
        sta data_ptr+1
        ldy #$00
        ldx #$01                        ; bcd_conv_digits+1..+3: 6 digits
game_over_score_loop
        lda bcd_conv_digits,x           ; high digit
        lsr
        lsr
        lsr
        lsr
        jsr draw_big_digit
        iny
        lda bcd_conv_digits,x           ; low digit
        and #$0f
        jsr draw_big_digit
        iny
        inx
        cpx #$04
        bcc game_over_score_loop
        lda SCROLY
        ora #$10
        sta SCROLY
        cli
; Wait 254 frames; then the other player's turn or, after 64 more frames, the title screen.
        lda #$fe                        ; wait 254 frames
        sta frame_countdown
game_over_wait
        lda frame_countdown
        bne game_over_wait
        lda option_two_players
        beq game_over_to_title
; not executed $1971-$1978
        lda inactive_player_state       ; other player still has falls
        bmi game_over_to_title
        jmp next_turn
game_over_to_title
        lda #$40
        sta frame_countdown
game_over_wait_title
        lda frame_countdown
        bne game_over_wait_title
        jmp show_title_screen
; Draw digit A (low nybble) as 2x2 characters of the logo charset: base character c = digit*4 + $B4. Upper
; row (row_ptr_top),y = c, lower row (data_ptr),y = c+1, then at Y+1: upper c+2, lower c+3. Output: Y
; advanced by 1. Called by game_over.
draw_big_digit
        and #$0f
        asl
        asl
        adc #$34                        ; glyph $34 + digit*4
        ora #$80                        ; bit 7: big font glyphs
        sta (row_ptr_top),y
        clc
        adc #$01
        sta (data_ptr),y
        clc
        adc #$01
        iny
        sta (row_ptr_top),y
        clc
        adc #$01
        sta (data_ptr),y
        rts
; Multiply mul8_value by 8 into the 16-bit value mul8_result_hi (high) : mul8_value (low). Used to turn a
; character code into a charset offset. Changes A.
word_times_8
        lda #$00
        sta mul8_result_hi
        clc
        rol mul8_value
        rol mul8_result_hi
        rol mul8_value
        rol mul8_result_hi
        rol mul8_value
        rol mul8_result_hi
        rts
